From 9ae9bea546c88e2fecb989177144970c1a5ba8d6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 00:21:29 +0100
Subject: [PATCH] libclock: don't show other time zones an hour off near local
 DST changes

jsDateTime() added the current offsets to now, but QML formats that
with the local offset of the result, so a DST change in between put it
an hour off. Return the wall time as local time and compare wall times.

BUG: 528109
---
 applets/digital-clock/main.qml | 2 +-
 libclock/clock.cpp             | 6 ++----
 2 files changed, 3 insertions(+), 5 deletions(-)

diff --git a/applets/digital-clock/main.qml b/applets/digital-clock/main.qml
index 5b983ef25b..1edc0c72df 100644
--- a/applets/digital-clock/main.qml
+++ b/applets/digital-clock/main.qml
@@ -68,7 +68,7 @@ PlasmoidItem {
     }

     function formatOffset(dateTime: date): string {
-        const offset = Math.round((dateTime - currentClock.dateTime) / (1000 * 60));
+        const offset = Math.round((dateTime - currentClock.dateTime) / (1000 * 60)) - dateTime.getTimezoneOffset() + currentClock.dateTime.getTimezoneOffset();

         if (offset === 0) {
             return "";
diff --git a/libclock/clock.cpp b/libclock/clock.cpp
index f8f27c4bba..4b74160faf 100644
--- a/libclock/clock.cpp
+++ b/libclock/clock.cpp
@@ -110,12 +110,10 @@ void Clock::setTrackSeconds(bool trackSeconds)

 QDateTime Clock::jsDateTime() const
 {
-    const QDateTime nowUtc = QDateTime::currentDateTimeUtc();
-    auto systemTime = nowUtc.toTimeZone(QTimeZone::systemTimeZone());
-    auto tzTime = nowUtc.toTimeZone(m_timeZone);
+    const QDateTime tzTime = QDateTime::currentDateTimeUtc().toTimeZone(m_timeZone);

     // Javascript doesn't have a concept of timezones, only a value from UTC in the system timezone
-    return nowUtc.addSecs(-systemTime.offsetFromUtc() + tzTime.offsetFromUtc());
+    return QDateTime(tzTime.date(), tzTime.time(), QTimeZone::LocalTime);
 }

 QDateTime Clock::now() const
